/* Each row belongs to its place in the video. Board times point to an observed frame. */
const lectureTracks = [
[
[1,'모델링과 ERD',[
['00:06','현실 업무를 모델로 옮기기','학교에서 학생과 과목을 찾고, 학생이 과목을 수강한다는 관계를 데이터 구조로 표현한다.'],
['01:01','모델링의 세 특징','단순화는 필요한 사실만 남기는 것, 추상화는 공통 특징을 뽑는 것, 명확화는 뜻을 하나로 정하는 것이다.','강사가 가끔 출제된다며 단·추·명으로 기억하라고 한다.'],
['01:22','설계할 때의 유의사항','변화에 대응할 유연성, 불필요한 중복을 줄이는 유일성, 관계와 정의를 일치시키는 일관성을 구별한다.'],
['01:50','세 가지 관점','데이터 관점은 무엇을 관리하는지, 프로세스 관점은 무슨 일을 하는지, 상관 관점은 그 일이 어떤 데이터를 다루는지 묻는다.'],
['02:17','상관 관점과 CRUD','학생 정보를 등록·조회·수정·삭제하는 동작을 업무와 연결한다.',null,'02:17','학교 업무 → 학생·과목·수강 → 데이터베이스|상관 관점 → C 생성 · R 조회 · U 수정 · D 삭제'],
['02:42','개념·논리·물리 모델','업무 개념에서 출발해 속성과 식별자를 정하고 실제 DBMS의 저장 구조로 구체화한다.'],
['05:59','ERD 작성','엔터티를 찾아 배치한 뒤 관계를 연결하고, 관계명·차수·선택 여부를 표시한다.'],
['06:11','IE와 Barker 표기','표기마다 기호의 뜻이 다르므로 한 건을 기준으로 반대편의 최소·최대 건수를 읽는다.','강사는 IE가 자주 나오고 Barker도 나올 수 있다고 설명한다.','06:15','엔터티 배치 → 관계 연결 → 관계명·차수·선택 표시']]],
[8,'세 수준의 스키마',[['08:23','외부·개념·내부 스키마','사용자가 보는 구조, 전체 논리 구조, 실제 저장 구조를 나누고 한 수준의 변경이 다른 수준에 미치는 영향을 살핀다.',null,'09:10','외부: 개인별 관점 → 개념: 전체 구조 → 내부: 저장 방식']]],
[2,'엔터티',[['11:02','엔터티와 인스턴스','관리 대상의 종류가 엔터티이며 그 종류에 속한 실제 한 건이 인스턴스다.',null,'11:50','엔터티: 학생 → 인스턴스: 학생 한 명'],['13:19','엔터티 분류의 두 축','유형·개념·사건과 기본·중심·행위를 서로 다른 기준으로 묶는다.','강사는 다른 분류에 속하는 보기를 고르는 유형을 예로 든다.'],['14:02','사건 엔터티와 중심 엔터티','주문이 발생했다는 사실은 사건 엔터티의 사례다. 중심 엔터티는 업무 흐름에서 중요한 거래를 맡는다는 분류이므로 두 이름은 동시에 성립할 수 있다.']]],
[3,'속성과 도메인',[['15:14','속성의 분류','직접 수집한 기본속성, 설계하면서 부여한 설계속성, 계산해서 얻은 파생속성을 구별한다. 도메인은 값이 허용되는 범위다.',null,'15:55','기본: 직접 수집 | 설계: 관리용 부여 | 파생: 계산 결과'],['18:57','도메인은 자료형보다 구체적이다','점수를 정수로 정해도 150은 입력 가능하다. 허용 범위를 0~100으로 정해야 실제 점수의 의미까지 제한된다.']]],
[5,'관계와 교차 엔터티',[['19:23','관계의 의미','한쪽 한 건을 고정하고 반대쪽이 몇 건까지 연결되는지, 연결이 꼭 필요한지 읽는다.'],['20:15','존재 관계와 행위 관계','소속처럼 존재에 근거한 연결과 신청처럼 행위에서 생기는 연결을 나눈다.','강사는 이 구분의 출제 빈도를 낮게 설명한다.'],['21:17','선택과 필수를 양쪽에서 읽기','학생 한 명은 수강을 한 건도 하지 않을 수 있지만, 수강 한 건에는 학생 한 명이 필요하다. 최대 건수와 최소 건수를 따로 읽는다.'],['21:52','M:N 관계 해소','학생과 과목 사이에 수강을 두면 신청일처럼 연결 자체에 속한 사실을 저장할 수 있다.',null,'22:20','학생 1 → N 수강 N ← 1 과목']]],
[4,'식별자와 키',[['24:07','식별자 분류','주·보조, 내부·외부, 단일·복합, 본질·인조는 각각 다른 질문에 대한 분류다.',null,'24:40','대표성: 주·보조 | 구성: 단일·복합 | 생성: 본질·인조'],['25:08','보조식별자','대표로 고른 학번 외에 업무 규칙상 유일한 식별 수단이 있다면 보조식별자가 될 수 있다. 자주 검색하는 속성이라도 중복되면 식별자가 될 수 없다.'],['25:43','내부·외부 식별자','자기 엔터티에서 만든 식별자와 다른 엔터티와의 관계를 통해 받아 온 식별자를 구별한다.'],['26:09','단일·복합 식별자','학번 하나로 학생을 찾는 것은 단일, 학생번호와 과목코드를 함께 써야 수강을 찾는 것은 복합이다. 재수강을 허용하면 학기 등 추가 기준도 필요하다.']]],
[6,'식별관계와 비식별관계',[['27:14','식별관계와 비식별관계','부모의 키가 자식의 주식별자 안에 들어가는지 그림에서 확인한다.',null,'28:20','학생번호 → 수강의 PK 일부: 식별관계|학생번호 → 수강의 일반 FK: 비식별관계']]],
[4,'키와 후보키',[['28:40','후보키·기본키·대체키','유일성과 최소성을 만족한 후보 중 하나를 기본키로 선택한다. 나머지 후보가 대체키다.'],['29:06','키의 기출 언급','후보키와 슈퍼키는 최소성이 필요한지로 구별한다.','강사는 키가 기출에 등장한 적이 있다고 말한다.']]],
[7,'정규화',[['31:58','이상 현상','하나의 표에 다른 사실을 섞어 저장할 때 생기는 삽입·갱신·삭제 이상을 살핀다.',null,'32:50','한 사실을 여러 행에 저장 → 삽입·갱신·삭제 이상'],['35:17','함수적 종속','결정자 값이 같으면 종속되는 값도 같아야 한다. 복합키 전체에 의존하는지 일부에만 의존하는지 찾는다.'],['37:06','1·2·3정규형','원자값을 확인하고, 부분 종속과 이행 종속을 순서대로 분리한다.','강사는 제1·제2·제3정규형의 구별을 특히 강조한다.'],['40:01','3정규형으로 나누는 이유','점수만으로 학점이 결정된다는 가정에서 수강 키 → 점수 → 학점이 된다. 점수와 학점의 대응을 따로 두면 등급 기준을 수강 행마다 수정할 필요가 없다.']]],
[5,'조인과 계층 관계',[['40:44','나눈 표를 다시 연결하기','서로 나눈 표는 공통으로 참조하는 키를 통해 조인한다.',null,'41:00','분리된 두 표 → 대응하는 키끼리 연결 → 조인 결과'],['41:55','계층과 상호배타 관계','같은 엔터티 안에서 상위 대상을 참조하는 경우와 여러 관계 중 하나를 선택하는 경우를 구별한다.']]],
[9,'트랜잭션',[['43:05','하나로 처리할 작업','송금의 출금과 입금처럼 함께 확정하거나 취소해야 할 변경을 묶는다.'],['43:30','ACID','원자성·일관성·격리성·지속성 중 어느 성질을 묻는지 사례에 대응한다.','강사는 1·2과목에 모두 나오는 주제라고 짚는다.','43:50','A 계좌 −100 → 송금 → B 계좌 +100|중간 실패 → 두 변경 모두 취소'],['45:17','격리 문제','미확정 값을 읽는 경우, 같은 행의 값이 바뀐 경우, 조건에 맞는 행 집합이 바뀐 경우를 구별한다.','강사는 이 부분은 개념 위주로 살핀다고 설명한다.','45:17','미확정 값 → Dirty Read | 같은 행의 값 변화 → Non-repeatable Read | 조건을 만족하는 행 집합 변화 → Phantom Read']]],
[10,'NULL과 식별자 비교',[['45:32','NULL의 의미','미정이거나 해당하지 않는 값과 실제 0을 구별한다. 비교와 집계에 어떻게 반영되는지 확인한다.',null,'46:00','필수 속성 → 값 필요 | 선택 속성 → NULL 허용'],['48:01','본질·인조식별자','업무에 이미 있는 식별값과 새로 발급한 번호를 비교한다. 새 번호만으로 업무상 중복까지 막을 수 있는지 생각한다.',null,'49:09','수강신청번호 → 각 신청을 구분|학생번호 + 과목 → 같은 신청인지 점검']]]
],[
[1,'DBMS·SQL·관계대수',[['00:06','DB와 DBMS','저장된 데이터와 사용자의 요청을 받아 데이터를 관리하는 프로그램을 구별한다.'],['01:22','DBMS별 문법','강의의 공통 SQL 예제를 읽고 Oracle과 SQL Server에서 결과가 달라지는 지점을 구별한다.','강사가 시험 준비에서 두 제품을 중점적으로 다룬다고 설명한다.'],['02:46','SQL 명령 분류','행을 다루는 DML, 구조를 정의하는 DDL, 거래 경계의 TCL, 권한을 다루는 DCL을 구별한다.','강사는 명령을 역할별로 구분하는 문제를 언급한다.'],['04:46','관계대수','셀렉션은 행을 고르고 프로젝션은 열을 고른다. 조인은 조건에 맞는 행을 연결한다.',null,'05:15','셀렉션 → 행 선택 | 프로젝션 → 열 선택'],['06:20','관계대수 복습','연산의 이름을 보고 결과 표에 어떤 행과 열이 남는지 예상한다.','강사는 자주 나오지는 않아도 출제되는 항목이라고 설명한다.']]],
[2,'SELECT와 별칭',[['06:38','SELECT와 DISTINCT','FROM에서 대상 표를 찾고, 출력 열 조합을 기준으로 DISTINCT가 중복을 제거하는지 살핀다.',null,'08:25','SELECT → 출력 열 조합 → DISTINCT로 중복 제거'],['11:40','별칭','결과 열이나 테이블에 이름을 붙일 때 어느 절에서 그 별칭을 사용할 수 있는지 살핀다.']]],
[4,'단일행 함수',[['14:23','문자·숫자·날짜 함수','입력 한 행에서 문자열을 자르거나 숫자를 반올림해 결과값 하나를 만든다. 변환은 입력값과 결과 자료형을 함께 확인한다.',null,'15:45','문자 입력 → 문자 함수 → 행별 결과'],['17:19','ROUND와 TRUNC','Oracle에서 ROUND(12.96,1)은 소수 첫째 자리까지 반올림해 13이 되고 TRUNC(12.96,1)은 뒤를 버려 12.9다. 자리수와 버릴 위치부터 찾는다.']]],
[3,'집계와 NULL 함수',[['20:31','집계','COUNT(*)는 행을 세고 COUNT(열)은 해당 열이 NULL인 행을 빼고 센다.',null,'21:10','여러 행 → 집계 함수 → 그룹당 결과 한 값'],['23:01','NULL 처리','COALESCE는 처음 만나는 비NULL 값을 고른다. NULLIF는 두 값이 같을 때 NULL을 돌려준다.']]],
[4,'CASE',[['24:51','조건별 값 계산','WHEN을 위에서부터 검사해 처음 참인 가지의 결과를 반환한다.',null,'25:30','조건 1 참 → 첫 결과 | 거짓 → 다음 WHEN'],['25:41','Oracle의 DECODE','DECODE(코드, 1, 값A, 2, 값B, 기본값)는 코드가 1이면 값A, 2이면 값B를 돌려준다. 범위 조건이 여러 개라면 CASE WHEN으로 조건을 직접 적을 수 있다.']]],
[5,'WHERE와 조건',[['25:49','행을 거르는 조건','FROM에서 가져온 행 중 조건이 TRUE인 행만 남긴다.'],['26:06','판서의 FWGHSO','조건을 만족하는 행을 먼저 찾고 나서 출력할 열을 고른다.','강사는 시험 시작 때 해석 순서를 적어 두는 방법을 제시한다.','26:06','F FROM → W WHERE → G GROUP BY|H HAVING → S SELECT → O ORDER BY'],['29:03','LIKE 패턴','%는 0개 이상의 문자, 밑줄은 한 문자에 대응한다.',null,'29:25','LIKE → %: 0자 이상 | _: 한 문자'],['32:08','NULL 비교','값이 비었는지는 IS NULL로 확인한다. 일반적인 = NULL 비교는 UNKNOWN이 되어 WHERE를 통과하지 않는다.','강사는 NULL 판정을 문제로 만들기 좋다고 짚는다.'],['32:28','조건식의 우선순위','논리 연산은 NOT, AND, OR 순으로 해석하며 괄호가 있으면 묶인 조건부터 판단한다.','강사는 해석 순서를 물을 수 있다고 말한다.']]],
[6,'GROUP BY와 HAVING',[['32:30','그룹 만들기','개별 행을 걸러낸 뒤 같은 키끼리 묶고 그룹별 집계를 계산한다. 그룹 결과에 붙이는 조건은 HAVING이다.',null,'33:00','행 → 그룹으로 묶기 → 그룹 조건 검사']]],
[7,'정렬',[['35:35','ORDER BY','첫 번째 정렬값이 같을 때 다음 정렬 기준을 적용한다.',null,'35:50','첫 정렬 기준 → 동점에서 다음 기준'],['38:32','NULL의 기본 정렬','오름차순 기본값에서 Oracle은 NULL이 뒤, SQL Server는 앞에 온다.','강사가 제품별 차이를 시험에서 주의할 점으로 짚는다.']]],
[8,'조인',[['38:52','조인 결과 읽기','조건을 만족하는 행의 쌍마다 결과 한 행이 생긴다. 연결 열 값이 반복되면 결과 행도 늘어난다.'],['41:10','표준 조인','내부 조인은 짝이 있는 행만, 외부 조인은 보존하는 쪽의 짝 없는 행까지 남긴다.',null,'41:40','일치하는 쌍 → INNER JOIN | 보존하는 쪽의 짝 없는 행도 포함 → OUTER JOIN'],['43:04','NATURAL JOIN','두 표에서 이름이 같은 열들을 조인 기준으로 사용한다. 의도하지 않은 같은 이름의 열까지 조건에 포함되는지 살핀다.'],['43:33','CROSS JOIN','왼쪽 2행과 오른쪽 3행의 모든 쌍은 6행이다. 값이 같아야 한다는 조건이 없어도 결과가 만들어진다.'],['44:01','OUTER JOIN','LEFT JOIN에서 짝이 없는 왼쪽 행은 오른쪽 열이 NULL인 채 남는다. 이후 WHERE에서 오른쪽 값과의 일치를 요구하면 그 행이 제외될 수 있다.']]],
[9,'서브쿼리와 뷰',[['45:30','서브쿼리 위치','값 하나를 반환하는 조회와 FROM에서 중간 결과를 표처럼 사용하는 인라인 뷰를 구분한다.',null,'48:30','안쪽 SELECT → FROM의 중간 결과 → 바깥 SELECT'],['50:51','뷰의 장점','자주 쓰는 조회를 단순화하고 접근할 열과 행을 제한할 수 있다.','강사가 뷰의 장점을 출제 가능한 항목으로 짚는다.']]],
[10,'집합 연산',[['51:02','두 결과 합치기','대응하는 열을 맞춘 뒤 UNION은 중복을 제거하고 UNION ALL은 그대로 둔다. 교집합과 차집합도 같은 입력으로 비교한다.',null,'51:15','UNION ALL → 중복 유지 | UNION → 중복 제거']]],
[11,'그룹 함수',[['52:38','소계와 총계','ROLLUP은 순서에 따른 소계, CUBE는 가능한 조합, GROUPING SETS는 지정한 조합을 만든다.',null,'53:30','ROLLUP → 단계별 소계 | CUBE → 조합별 집계']]],
[12,'윈도우 함수',[['55:10','OVER와 윈도우 집계','분할과 순서를 정하고 원래 행을 보존하면서 집계값이나 순위를 붙인다.',null,'58:10','원래 각 행 → OVER가 정한 범위 → 행별 집계값'],['55:39','ROW_NUMBER·RANK·DENSE_RANK','점수가 90, 90, 80이면 RANK는 1·1·3, DENSE_RANK는 1·1·2다. ROW_NUMBER는 각 행에 서로 다른 번호를 준다. 동점 안에서 순서를 고정하려면 추가 정렬 기준이 필요하다.'],['59:20','행간 함수','LAG와 LEAD는 파티션 안에서 앞이나 뒤의 행 값을 가져온다.'],['62:03','프레임','ROWS는 행 위치를, RANGE는 정렬값의 범위를 기준으로 계산한다. 동점에서 차이가 드러난다.',null,'63:30','ROWS → 행 위치 | RANGE → 정렬값 범위'],['65:03','분포 함수와 NTILE','NTILE(3)은 정렬된 행을 크기가 최대 한 행 차이 나는 세 그룹으로 나눈다. 8행이면 앞에서부터 3·3·2행이다. 같은 값이 반드시 같은 그룹을 받는 것은 아니다.']]],
[7,'상위 N개',[['65:40','상위 N개와 동점','상위 매출 두 건을 찾는다면 먼저 매출 내림차순으로 정렬한다. SQL Server의 TOP (2)는 두 행을 고르고, WITH TIES는 두 번째 행과 정렬 기준이 같은 행까지 포함한다.'],['67:09','Oracle에서 ROWNUM으로 행 제한하기','같은 조회 단계에서 ROWNUM = 2를 쓰면 첫 후보의 번호 1부터 조건을 통과하지 못한다. 처음 두 행은 ROWNUM <= 2로 고른다. 매출 상위 두 건이면 안쪽 조회에서 먼저 정렬하고 바깥에서 행 수를 제한한다.',null,'68:40','첫 후보 1 ≤ 2 → 통과 | 둘째 후보 2 ≤ 2 → 통과 | 셋째 후보 3 ≤ 2 → 제외']]],
[13,'계층형 질의',[['69:14','부모와 자식 탐색','START WITH에서 시작 행을 정하고 CONNECT BY로 이어질 행을 찾는다.'],['70:00','아래로 내려가는 방향','상사가 없는 사원을 루트로 삼는다. CONNECT BY PRIOR 사원번호 = 상사번호라면 직전 행의 사원번호를 상사번호로 가진 부하가 다음 행이다.'],['70:35','LEVEL과 역방향 탐색','루트의 LEVEL은 1이고 한 번 내려갈 때마다 1씩 커진다. 특정 사원부터 상사를 거슬러 올라가려면 출발 조건과 연결 방향을 함께 바꾼다.'],['71:20','셀프 조인','같은 사원 표에 직원 E와 상사 M이라는 두 별칭을 붙인다. E.상사번호 = M.사원번호로 연결하면 한 행에서 직원과 직속 상사를 함께 읽을 수 있다.']]],
[14,'PIVOT과 정규표현식',[['71:47','행·열 변환','PIVOT은 분류값을 결과 열로 펼치며 집계하고, UNPIVOT은 여러 열을 행 방향으로 모은다.',null,'71:50','분류값이 있는 행 → PIVOT → 분류별 열'],['72:35','문자 패턴','문자 범위와 반복 기호, 시작과 끝 표시를 읽어 어떤 문자열이 일치하는지 확인한다.'],['73:17','복습 범위','기본 패턴부터 판별하고 다른 단원과 복습 시간을 나눈다.','강사는 정규표현식의 예상 비중을 낮게 설명한다.']]],
[15,'데이터 변경',[['73:43','DML','INSERT는 행을 추가하고 UPDATE는 값을 바꾸고 DELETE는 행을 지운다. 대상 행의 조건을 먼저 읽는다.',null,'74:20','대상 열 목록 + 입력 값 → 새 행'],['75:05','MERGE','원본과 대상의 조건이 일치하는지 먼저 판단한다. 일치하면 기존 행을 수정하고, 일치하지 않으면 새 행을 넣도록 한 문장에서 지정할 수 있다.']]],
[16,'트랜잭션 제어',[['75:57','TCL','COMMIT·ROLLBACK으로 변경을 확정하거나 취소한다. 변경을 실행한 시점과 확정한 시점을 구별한다.'],['77:01','저장점과 부분 취소','A를 수정하고 저장점 S를 찍은 뒤 B를 고쳤다면 ROLLBACK TO S는 B의 수정만 취소한다. A의 수정은 남아 있지만 아직 커밋된 것은 아니다.'],['78:38','자동 커밋','문장 하나가 끝날 때 자동으로 확정되는 환경인지 먼저 읽는다. 이미 커밋한 변경은 나중에 실행한 ROLLBACK으로 취소할 수 없다. 실제 기본 동작은 DBMS와 접속 도구 설정을 함께 확인한다.',null,'78:40','문장 성공 → 자동 커밋이면 확정 | 명시적 거래 안 → COMMIT 또는 ROLLBACK 확인']]],
[17,'객체 정의',[['79:10','DDL','표의 생성·변경·제거와 제약조건을 구별한다. 행 제거와 구조 제거는 결과가 다르다.',null,'80:30','테이블 정의 → 열·자료형·제약 지정'],['82:44','DELETE·TRUNCATE·DROP','DELETE는 조건으로 행을 고를 수 있고 TRUNCATE는 표의 정의를 남기며 전체 데이터를 비운다. DROP TABLE은 표 정의까지 제거한다. 롤백 여부를 물을 때는 DBMS를 확인한다.']]],
[18,'권한 부여와 회수',[['83:18','GRANT와 REVOKE','누가 어떤 객체 권한을 받았고 다시 부여할 수 있는지 경로를 따라간다.',null,'84:05','소유자 → USER1 → USER2|객체 권한 재부여 → WITH GRANT OPTION'],['84:15','Oracle에서 권한을 다시 부여하는 옵션','WITH GRANT OPTION은 객체 권한, WITH ADMIN OPTION은 시스템 권한이나 역할에 붙인다. A에게서 권한을 받은 B를 생각하자. Oracle에서 A의 객체 권한을 회수하면 그 경로로 B에게 준 권한도 회수된다. 시스템 권한을 ADMIN OPTION으로 받아 전달했다면 A의 권한을 회수해도 B에게 부여한 권한은 그대로다. 다른 부여 경로가 있는지도 별도로 확인한다.']]]
]];
